export const isAutomorphic = (n) => {
  if (typeof n !== 'number') {
    throw new Error('Type of n must be number')
  }
  if (!Number.isInteger(n)) {
    throw new Error('n cannot be a floating point number')
  }
  if (n < 0) {
    return false
  }

  let n_sq = n * n
  while (n > 0) {
    if (n % 10 !== n_sq % 10) {
      return false
    }
    n = Math.floor(n / 10)
    n_sq = Math.floor(n_sq / 10)
  }

  return true
}

const mean = (numbers) => {
  if (!Array.isArray(numbers)) {
    throw new TypeError('Invalid Input')
  } else if (numbers.length === 0) {
    throw new Error('Array is empty')
  }

  let total = 0
  numbers.forEach((num) => {
    if (typeof num !== 'number') {
      throw new TypeError('Invalid Input')
    }
    total += num
  })

  return total / numbers.length
}

export { mean }

const averageMedian = (sourceArrayOfNumbers) => {
  const numbers = [...sourceArrayOfNumbers].sort(sortNumbers)
  const numLength = numbers.length

  return numLength % 2 === 0
    ? (numbers[numLength / 2 - 1] + numbers[numLength / 2]) / 2
    : numbers[Math.floor(numLength / 2)]
}

const sortNumbers = (num1, num2) => num1 - num2

