const calcRange = (num) => {
  return [...Array(num).keys()].map((i) => i + 1)
}

const calcFactorial = (num) => {
  if (num === 0) {
    return 1
  }
  if (num < 0) {
    throw Error('Sorry, factorial does not exist for negative numbers.')
  }
  if (!num) {
    throw Error(
      'Sorry, factorial does not exist for null or undefined numbers.'
    )
  }
  if (num > 0) {
    const range = calcRange(num)
    const factorial = range.reduce((a, c) => a * c, 1)
    return factorial
  }
}

export { calcFactorial }

function fareyApproximation(decimal, repeat = 20) {
  let a = 0
  let b = 1
  let c = 1
  let d = 1
  let numerator
  let denominator

  for (let i = 0; i < repeat; i++) {
    numerator = a + c
    denominator = b + d

    if (decimal > numerator / denominator) {
      ;[a, b] = [numerator, denominator]
    } else {
      ;[c, d] = [numerator, denominator]
    }
  }

  return { numerator, denominator }
}

export { fareyApproximation }

const findHCF = (x, y) => {

  if (x < 1 || y < 1) {
    return 'Please enter values greater than zero.'
  }

  if (x !== Math.round(x) || y !== Math.round(y)) {
    return 'Please enter whole numbers.'
  }

  while (Math.max(x, y) % Math.min(x, y) !== 0) {
    if (x > y) {
      x %= y
    } else {
      y %= x
    }
  }

  return Math.min(x, y)
}

export { findHCF }

