const parityOutlier = (integers) => {
  let oddsCount = 0 
  let evensCount = 0 
  let odd, even

  for (const e of integers) {
    if (!Number.isInteger(e)) {

      return null
    }
    if (e % 2 === 0) {

      even = e
      evensCount++
    } else {

      odd = e
      oddsCount++
    }
  }

  if (oddsCount === 0 || evensCount === 0) return null 
  if (oddsCount > 1 && evensCount > 1) return null 

  return oddsCount === 1 ? odd : even
}

export { parityOutlier }

const addRow = (triangle) => {
  const previous = triangle[triangle.length - 1]
  const newRow = [1]
  for (let i = 0; i < previous.length - 1; i++) {
    const current = previous[i]
    const next = previous[i + 1]
    newRow.push(current + next)
  }
  newRow.push(1)
  return triangle.push(newRow)
}

const generate = (numRows) => {
  const triangle = [[1], [1, 1]]

  if (numRows === 0) {
    return []
  } else if (numRows === 1) {
    return [[1]]
  } else {
    for (let i = 2; i < numRows; i++) {
      addRow(triangle)
    }
  }
  return triangle
}

export { generate }

const factorsExcludingNumber = (n) => {
  return [...Array(n).keys()].filter((num) => n % num === 0)
}

const perfectNumber = (n) => {
  const factorSum = factorsExcludingNumber(n).reduce((num, initialValue) => {
    return num + initialValue
  }, 0)

  return factorSum === n
}

