def min_steps_to_one(number: int) -> int:

    if number <= 0:
        msg = f"n must be greater than 0. Got n = {number}"
        raise ValueError(msg)

    table = [number + 1] * (number + 1)

    table[1] = 0
    for i in range(1, number):
