    if r_initial <= 0 or r_final <= 0:
        raise ValueError("Orbital radii must be greater than zero.")

    work = (gravitational_constant * mass_central * mass_object / 2) * (
        1 / r_initial - 1 / r_final
    )
    return f"{work:.3e}"

