final class DP {
    private DP() {
    }

    public static long findWays(int m, int n, int x) {

        long[][] table = new long[n + 1][x + 1];

        for (int j = 1; j <= m && j <= x; j++) {
            table[1][j] = 1;
        }

        for (int i = 2; i <= n; i++) {
            for (int j = 1; j <= x; j++) {
                for (int k = 1; k < j && k <= m; k++) {
                    table[i][j] += table[i - 1][j - k];
                }
            }
        }

        return table[n][x];
    }
}

package com.thealgorithms.dynamicprogramming;

import java.util.HashMap;

@SuppressWarnings({"rawtypes", "unchecked"})
final class LongestArithmeticSubsequence {
    private LongestArithmeticSubsequence() {
    }

    public static int getLongestArithmeticSubsequenceLength(int[] nums) {
        if (nums == null) {
            throw new IllegalArgumentException("Input array cannot be null");
        }

        if (nums.length <= 1) {
            return nums.length;
        }

        HashMap<Integer, Integer>[] dp = new HashMap[nums.length];
        int maxLength = 2;

        for (int i = 0; i < nums.length; i++) {
            dp[i] = new HashMap<>();
            for (int j = 0; j < i; j++) {
                final int diff = nums[i] - nums[j];
                dp[i].put(diff, dp[j].getOrDefault(diff, 1) + 1);
                maxLength = Math.max(maxLength, dp[i].get(diff));
            }
        }

        return maxLength;
    }
}

