        if (targetSum < 0) {
            return false; 
        }

        boolean[] dp = new boolean[targetSum + 1];
        dp[0] = true; 

        for (int number : nums) {
            for (int j = targetSum; j >= number; j--) {
                dp[j] = dp[j] || dp[j - number];
            }
        }

        return dp[targetSum];
    }
}

