            return 0;
        }

        Arrays.sort(queries);

        int totalWaitingTime = 0;
        for (int i = 0; i < n; i++) {
            totalWaitingTime += queries[i] * (n - i - 1);
        }
        return totalWaitingTime;
    }
}

