class ExchangeSort implements SortAlgorithm {

    @Override
    public <T extends Comparable<T>> T[] sort(T[] array) {
        for (int i = 0; i < array.length - 1; i++) {
            for (int j = i + 1; j < array.length; j++) {
                if (SortUtils.greater(array[i], array[j])) {
                    SortUtils.swap(array, i, j);
                }
            }
        }
        return array;
    }
}

package com.thealgorithms.sorts;

public class GnomeSort implements SortAlgorithm {

    @Override
    public <T extends Comparable<T>> T[] sort(final T[] array) {
        int i = 1;
        int j = 2;
        while (i < array.length) {
            if (SortUtils.less(array[i - 1], array[i])) {
                i = j++;
            } else {
                SortUtils.swap(array, i - 1, i);
                if (--i == 0) {
                    i = j++;
                }
            }
        }

        return array;
    }
}

package com.thealgorithms.sorts;

public class PancakeSort implements SortAlgorithm {

    @Override
    public <T extends Comparable<T>> T[] sort(T[] array) {
        if (array.length < 2) {
            return array;
        }

        for (int currentSize = 0; currentSize < array.length; currentSize++) {
            int maxIndex = findIndexOfMax(array, currentSize);
            SortUtils.flip(array, maxIndex, array.length - 1 - currentSize);
        }

        return array;
    }

    private <T extends Comparable<T>> int findIndexOfMax(T[] array, int currentSize) {
        T max = array[0];
        int maxIndex = 0;
        for (int i = 0; i < array.length - currentSize; i++) {
            if (SortUtils.less(max, array[i])) {
                max = array[i];
                maxIndex = i;
            }
        }
        return maxIndex;
    }
}

package com.thealgorithms.sorts;

public class SelectionSort implements SortAlgorithm {

    @Override
    public <T extends Comparable<T>> T[] sort(T[] array) {

        for (int i = 0; i < array.length - 1; i++) {
            final int minIndex = findIndexOfMin(array, i);
            SortUtils.swap(array, i, minIndex);
        }
        return array;
    }

    private static <T extends Comparable<T>> int findIndexOfMin(T[] array, final int startIndex) {
        int minIndex = startIndex;
        for (int i = startIndex + 1; i < array.length; i++) {
            if (SortUtils.less(array[i], array[minIndex])) {
                minIndex = i;
            }
        }
        return minIndex;
    }
}

package com.thealgorithms.sorts;

public class SlowSort implements SortAlgorithm {

    @Override
    public <T extends Comparable<T>> T[] sort(T[] unsortedArray) {
        sort(unsortedArray, 0, unsortedArray.length - 1);
        return unsortedArray;
    }

    private <T extends Comparable<T>> void sort(T[] array, int i, int j) {
        if (SortUtils.greaterOrEqual(i, j)) {
            return;
        }
        final int m = (i + j) >>> 1;
        sort(array, i, m);
        sort(array, m + 1, j);
        if (SortUtils.less(array[j], array[m])) {
            SortUtils.swap(array, j, m);
        }
        sort(array, i, j - 1);
    }
}

