template <size_t N>
int maxSubArray(const std::array<int, N> &n) {
    int curr_sum =
        0;  
    int max_sum = INT_MIN;  
    for (int i : n) {  
        curr_sum += n[i];
        max_sum = std::max(max_sum, curr_sum);  
