using namespace std;
int LIS(const std::vector<int>& arr, int n) {
    set<int> active;  
    active.insert(arr[0]);

    for (int i = 1; i < n; ++i) {
        auto get = active.lower_bound(arr[i]);
        if (get == active.end()) {
            active.insert(arr[i]);
        }  
        else {
            int val = *get;  

            if (val > arr[i]) {

                active.erase(get);
                active.insert(arr[i]);
            }
        }
    }
    return active.size();  
}

